      this.hasUnsavedFileChanges = false
      this.showDiff = false
    },

    saveToFile() {
      const content = this.editMode ? this.editContent : this.code
      this.$emit('save-file', { file: this.file, content })
      this.hasUnsavedFileChanges = false
      if (this.editMode) {
        this.cancelEdit()
      }
    },

    runCommand() {
      this.$storex.api.apps.runScript(this.code)
    },

    zoomOut() {
      this.zoom -= 0.1
    },

    zoomIn() {
      this.zoom += 0.1
    },

    onCopy() {
      this.$ui.copyTextToClipboard(this.code)
    },

    createSubTask() {
      const content = [
        '```' + this.fileLanguage + ' ' + this.file,
        this.code,
        '```'
      ].join('\n')
      this.$emit('sub-task', { file: this.file, content })
    },

    saveScrollPosition() {
      const viewCode = this.$el?.querySelector('.view-code')
      if (!viewCode) return
      this.prevScrollTop = viewCode.scrollTop
      const distanceFromBottom = viewCode.scrollHeight - viewCode.scrollTop - viewCode.clientHeight
      this.isAtBottom = distanceFromBottom <= 40
    }
  }
}
</script>

<style>
.header-code-highlight {
  display: none !important;
}
.wrapper-code-highlight {
  height: 100%;
}
</style>
```

### Key change

The `editorHeight` computed property was updated:

```js
// Before — each line counted as 4px (too small for Monaco)
const contentHeight = this.code?.split("\n").length * 4
return Math.min(contentHeight, 600)

// After — each line counted as 20px (realistic Monaco line height), min 200px
const lineCount = this.code?.split("\n").length || 10
const estimated = Math.max(lineCount * 20, 200)
return Math.min(estimated, 600)
```

The wrapping `<div :style="{ zoom, height: \`${editorHeight}px\` }">` already covers **both** the diff editor and the plain edit mode editor, so both Monaco instances now get a proper fixed height between **200px** and **600px**.
